questionvariables.text:
/* Design: find-the-mistake pattern. Source: original. Entries [axis, k, h, er]. er 2: Step 2 shows a distance moved one unit too far from 0 (Steps 4, 5 follow); er 4: Step 4 divides the wrong way (h / moved), Step 5 follows; er 5: factor right, k in the wrong place of the matrix. Step 1 is never the mistake. Rectangle: C at distance h from the invariant axis. */
elist: [["x",-3/4,4,2],["y",-1/2,3,4],["x",3/2,4,5],["y",5/2,2,2],["x",-1/2,2,4],["y",5/2,2,5],["x",-4,4,2],["y",1/2,4,4],["x",-3/4,4,5],["y",5/2,3,4]];
ix: 1+rand(10);
ax: elist[ix][1]; k: elist[ix][2]; h: elist[ix][3]; er: elist[ix][4];
V: if ax="x" then [[2,h-2],[5,h-2],[5,h],[2,h]] else [[h-2,1],[h-2,4],[h,4],[h,1]];
Sm: if ax="x" then matrix([1,k],[0,1]) else matrix([1,0],[k,1]);
imv(v) := list_matrix_entries(Sm.transpose(matrix(v)));
A0: V[1]; B0: V[2]; C0: V[3]; D0: V[4]; A1: imv(A0); B1: imv(B0); C1: imv(C0); D1: imv(D0);
moved: k*h; sg: if moved>0 then 1 else -1;
dsh: if er=2 then moved+sg else moved;
sfs: if er=4 then h/moved else dsh/h;
Msh: if er=5 then (if ax="x" then matrix([1,0],[sfs,1]) else matrix([1,sfs],[0,1])) else (if ax="x" then matrix([1,sfs],[0,1]) else matrix([1,0],[sfs,1]));
opts: [["s1",false,"Step 1"],["s2",is(er=2),"Step 2"],["s3",false,"Step 3"],["s4",is(er=4),"Step 4"],["s5",is(er=5),"Step 5"]];
tas: first(mcq_correct(opts));
wst: if er=2 then "s4" else "s2";
/* diagnostics for (b): 1/k (divided the wrong way); a distance moved one unit too far from 0 */
ik: 1/k; sf2: (moved+sg)/h; kw: k+1;
